test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// --- brickHit: ball bounces off bricks (ISSUES.md #1) ----------------------

// A ball moving DOWN that reaches the top face of a brick must be deflected
// back UP (vy flips), the other component must stay untouched, and the ball
// must be pushed out of the brick so it does not stick.
test('brickHit: top face — ball heading down bounces up, pushed out', () => {
  const ball = { x: 136, y: 105, r: 7, vx: 40, vy: 300, px: 136, py: 90 };
  const bricks = [{ x: 100, y: 100, w: 72, h: 20, alive: true }];
  const broken = brickHit(ball, bricks);

  assert.deepEqual(broken, bricks);
  assert.equal(bricks[0].alive, false);
  assert.equal(ball.vy, -300, 'vertical component flips');
  assert.equal(ball.vx, 40, 'horizontal component untouched');
  assert.equal(ball.y, 100 - 7, 'pushed out above the brick');
  assert.equal(collides(ball, bricks[0]), false);
});

// A ball moving RIGHT that reaches the left face of a brick must be deflected
// back LEFT (vx flips), with vy untouched.
test('brickHit: side face — horizontal flip, vertical untouched', () => {
  const ball = { x: 105, y: 110, r: 7, vx: 300, vy: 120, px: 90, py: 110 };
  const bricks = [{ x: 100, y: 100, w: 72, h: 20, alive: true }];
  brickHit(ball, bricks);

  assert.equal(ball.vx, -300, 'horizontal component flips');
  assert.equal(ball.vy, 120, 'vertical component untouched');
  assert.equal(ball.x, 100 - 7, 'pushed out left of the brick');
  assert.equal(collides(ball, bricks[0]), false);
});

// A ball heading UP into the bottom face bounces back DOWN.
test('brickHit: bottom face — ball heading up bounces down', () => {
  const ball = { x: 136, y: 105, r: 7, vx: 0, vy: -300, px: 136, py: 130 };
  const bricks = [{ x: 100, y: 100, w: 72, h: 20, alive: true }];
  brickHit(ball, bricks);

  assert.equal(ball.vy, 300, 'vertical component flips');
  assert.equal(ball.y, 100 + 20 + 7, 'pushed out below the brick');
  assert.equal(collides(ball, bricks[0]), false);
});

// Diagonal entry through a brick corner: BOTH components flip.
test('brickHit: corner — both axes flip', () => {
  const ball = { x: 100, y: 100, r: 7, vx: 300, vy: 300, px: 88, py: 88 };
  const bricks = [{ x: 100, y: 100, w: 72, h: 20, alive: true }];
  brickHit(ball, bricks);

  assert.equal(ball.vx, -300);
  assert.equal(ball.vy, -300);
  assert.equal(collides(ball, bricks[0]), false);
});

// The grid gap is 8px and the ball 14px across, so every seam overlaps TWO
// bricks in the same pass. Bouncing per brick would flip vy twice and cancel
// out — the ball must bounce exactly once, off the shared top face.
test('brickHit: seam between two bricks — bounce applied exactly once', () => {
  const ball = { x: 176, y: 105, r: 7, vx: 0, vy: 300, px: 176, py: 90 };
  const bricks = [
    { x: 100, y: 100, w: 72, h: 20, alive: true },
    { x: 180, y: 100, w: 72, h: 20, alive: true },
  ];
  const broken = brickHit(ball, bricks);

  assert.equal(broken.length, 2, 'both seam bricks are hit');
  assert.ok(bricks.every((b) => !b.alive));
  assert.equal(ball.vy, -300, 'vy flips exactly once (not twice)');
  assert.equal(ball.vx, 0, 'vx untouched');
  assert.equal(ball.y, 93, 'pushed out above the seam');
});

// At level 6 the ball covers 35.5px per capped 50ms frame while a brick plus
// the ball diameter only spans 34px: the discrete test misses it entirely.
// The swept test must still catch the brick and bounce the ball.
test('brickHit: tunnelling — fast ball jumping the whole brick is caught', () => {
  const ball = { x: 136, y: 130, r: 7, vx: 0, vy: 500, px: 136, py: 80 };
  const bricks = [{ x: 100, y: 100, w: 72, h: 20, alive: true }];
  const broken = brickHit(ball, bricks);

  assert.equal(broken.length, 1);
  assert.equal(bricks[0].alive, false);
  assert.equal(ball.vy, -500);
  assert.equal(collides(ball, bricks[0]), false);
});

// No overlap at all: nothing is destroyed and the ball is untouched.
test('brickHit: no collision — nothing broken, ball untouched', () => {
  const ball = { x: 300, y: 300, r: 7, vx: 100, vy: 100, px: 300, py: 300 };
  const bricks = [{ x: 100, y: 100, w: 72, h: 20, alive: true }];
  const broken = brickHit(ball, bricks);

  assert.deepEqual(broken, []);
  assert.equal(bricks[0].alive, true);
  assert.equal(ball.vx, 100);
  assert.equal(ball.vy, 100);
});

