```js
// --- Brick collision resolution (pure, tested) ------------------------------

// Penetration-based face guess: which face of `brick` the ball overlaps most
// cleanly. Only meaningful when the ball already overlaps the brick at the
// current position — the swept test below is preferred, because it is accurate
// in time (the penetration guess misreads deep overlaps and seams, see #1).
function penetrationFace(ball, brick) {
  const overlapX =
    Math.min(ball.x + ball.r, brick.x + brick.w) - Math.max(ball.x - ball.r, brick.x);
  const overlapY =
    Math.min(ball.y + ball.r, brick.y + brick.h) - Math.max(ball.y - ball.r, brick.y);

  // The axis with the SMALLER penetration is the face that was hit: the ball
  // has only just crossed that face, so it has barely dug in along that axis.
  if (overlapX < overlapY) {
    // side hit: push the ball out toward the side its center sits on
    return { axis: 'x', dir: ball.x < brick.x + brick.w / 2 ? LEFT : RIGHT };
  }
  if (overlapY < overlapX) {
    return { axis: 'y', dir: ball.y < brick.y + brick.h / 2 ? UP : DOWN };
  }
  // equal penetration: a diagonal (corner) hit, flip both axes
  return { axis: 'both' };
}

// Swept entry test (Liang–Barsky slab method). Does the ball centre path from
// (px, py) to (x, y) enter the brick's rectangle EXPANDED by the ball radius,
// and through which face? This catches tunnelling (a fast ball jumping a whole
// brick between two frames) and resolves seam hits on the correct shared face
// (the per-brick penetration guess misreads those as side hits, see #1).
function sweptFace(px, py, x, y, ball, brick) {
  const r = ball.r;
  const minX = brick.x - r;
  const maxX = brick.x + brick.w + r;
  const minY = brick.y - r;
  const maxY = brick.y + brick.h + r;
  const dx = x - px;
  const dy = y - py;

  let tEnter = 0; // first contact time, as a fraction of the move (0..1)
  let tExit = 1;  // last contact time
  let axis = null;
  let dir = 0;
  let corner = false;

  // X slab: time interval during which the centre is inside the expanded X span.
  if (dx === 0) {
    if (px <= minX || px >= maxX) return null; // moving parallel, never entering
  } else {
    const t1 = (minX - px) / dx;
    const t2 = (maxX - px) / dx;
    const near = Math.min(t1, t2);
    const far = Math.max(t1, t2);
    if (near > tEnter) {
      tEnter = near;
      axis = 'x';
      dir = dx > 0 ? LEFT : RIGHT; // moving right enters through the left face
    }
    tExit = Math.min(tExit, far);
  }

  // Y slab.
  if (dy === 0) {
    if (py <= minY || py >= maxY) return null;
  } else {
    const t1 = (minY - py) / dy;
    const t2 = (maxY - py) / dy;
    const near = Math.min(t1, t2);
    const far = Math.max(t1, t2);
    if (near >= tEnter) {
      if (axis !== null && near - tEnter < EPS) {
        corner = true; // both faces crossed at (almost) the same instant
      } else {
        tEnter = near;
        axis = 'y';
        dir = dy > 0 ? UP : DOWN; // moving down enters through the top face
      }
    }
    tExit = Math.min(tExit, far);
  }

  if (axis === null) return null; // started inside the expanded rect: no entry face
  if (tEnter > tExit || tEnter > 1 || tExit < 0) return null;

  if (corner) return { face: { axis: 'both' }, t: tEnter };
  return { face: { axis, dir }, t: tEnter };
}

// Applies the single bounce decided by brickHit: flips the hit component(s)
// and repositions the ball flush against the face it hit, so the next frame
// does not re-detect the same overlap (no sticky re-flip).
function resolveBounce(ball, brick, face) {
  if (face.axis === 'x' || face.axis === 'both') {
    const dir = face.dir ?? (ball.x < brick.x + brick.w / 2 ? LEFT : RIGHT);
    ball.vx = dir * Math.abs(ball.vx);
    ball.x = dir === LEFT ? brick.x - ball.r : brick.x + brick.w + ball.r;
  }
  if (face.axis === 'y' || face.axis === 'both') {
    const dir = face.dir ?? (ball.y < brick.y + brick.h / 2 ? UP : DOWN);
    ball.vy = dir * Math.abs(ball.vy);
    ball.y = dir === UP ? brick.y - ball.r : brick.y + brick.h + ball.r;
  }
}

// Resolves every ball-vs-brick collision of one frame and destroys the bricks
// hit. Applies exactly ONE bounce, based on the earliest contact: at a seam
// the same pass overlaps two bricks, and flipping vy for each would cancel out
// (see #1). `ball.px` / `ball.py` — recorded by step() — feed the swept test
// against tunnelling; on a freshly created ball they are missing and the test
// falls back to the current position. Returns the destroyed bricks so the
// caller can score them.
export function brickHit(ball, bricks) {
  const px = ball.px ?? ball.x;
  const py = ball.py ?? ball.y;

  let primary = null; // { brick, face, t } — the single bounce to apply
  const broken = [];

  for (const brick of bricks) {
    if (!brick.alive) continue;

    let face = null;
    let t = 0;
    const swept = sweptFace(px, py, ball.x, ball.y, ball, brick);
    if (swept) {
      face = swept.face;
      t = swept.t;
    } else if (collides(ball, brick)) {
      // The ball started the frame already inside the expanded rectangle
      // (sweptFace returns null): fall back to the current-position test.
      face = penetrationFace(ball, brick);
    }
    if (!face) continue;

    brick.alive = false;
    broken.push(brick);
    if (primary === null || t < primary.t) {
      primary = { brick, face, t };
    }
  }

  if (primary !== null) {
    resolveBounce(ball, primary.brick, primary.face);
  }
  return broken;
}
