// and repositions the ball flush against the face it hit, so the next frame
// does not re-detect the same overlap (no sticky re-flip).
function resolveBounce(ball, brick, face) {
  if (face.axis === 'x' || face.axis === 'both') {
    const dir = face.dir ?? (ball.x < brick.x + brick.w / 2 ? LEFT : RIGHT);
    ball.vx = dir * Math.abs(ball.vx);
    ball.x = dir === LEFT ? brick.x - ball.r : brick.x + brick.w + ball.r;
  }
  if (face.axis === 'y' || face.axis === 'both') {
    const dir = face.dir ?? (ball.y < brick.y + brick.h / 2 ? UP : DOWN);
    ball.vy = dir * Math.abs(ball.vy);
    ball.y = dir === UP ? brick.y - ball.r : brick.y + brick.h + ball.r;
  }
}

// Resolves every ball-vs-brick collision of one frame and destroys the bricks
// hit. Applies exactly ONE bounce, based on the earliest contact: at a seam
// the same pass overlaps two bricks, and flipping vy for each would cancel out
// (see #1). `ball.px` / `ball.py` — recorded by step() — feed the swept test
// against tunnelling; on a freshly created ball they are missing and the test
// falls back to the current position. Returns the destroyed bricks so the
// caller can score them.
export function brickHit(ball, bricks) {
  const px = ball.px ?? ball.x;
  const py = ball.py ?? ball.y;

  let primary = null; // { brick, face, t } — the single bounce to apply
  const broken = [];

  for (const brick of bricks) {
    if (!brick.alive) continue;

    let face = null;
    let t = 0;
    const swept = sweptFace(px, py, ball.x, ball.y, ball, brick);
    if (swept) {
      face = swept.face;
      t = swept.t;
    } else if (collides(ball, brick)) {
      // The ball started the frame already inside the expanded rectangle
      // (sweptFace returns null): fall back to the current-position test.
      face = penetrationFace(ball, brick);
    }
    if (!face) continue;

    brick.alive = false;
    broken.push(brick);
    if (primary === null || t < primary.t) {
      primary = { brick, face, t };
    }
  }

  if (primary !== null) {
    resolveBounce(ball, primary.brick, primary.face);
  }
  return broken;
}

