edits.newText:
// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. Brick collisions are resolved separately by
// brickHit(), called from the game loop — not here (see ISSUES.md #2).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  // Remember where this move started: brickHit() sweeps between the two
  // positions so a fast ball cannot tunnel through a brick (see #1).
  ball.px = ball.x;
  ball.py = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

